head.script:
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    dataList1.setJSON(scwin.data);
};
scwin.trigger2_onclick = function(e) {
    dataList1.removeAll();
    gridView1.initGrid();
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1__text', 'key-sequence', {
        sequence: "22"
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+$p.id+'gridView1_cell_0_0').style.backgroundColor != ''", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
